// 2025-1-11 16:47:02
// 准周期点阵

#define PI 3.1415926535

void mainImage(out vec4 o, vec2 u) {
        float p, N = floor(mod(iTime * 4., 4. * 30.)) + 3.;
        vec2 R = iResolution.xy, V, s;
        u = 20. * (u + u - R) / R.y;

        //// golden spiral   10s
        if (abs(iTime - 10.) < .55) u *= 5., N = 50.;

        for (float i = 0.; i < N; i++) {
                V = sqrt(2. / N) * cos(PI / N * i + vec2(0, 11));
                p = round(dot(u, V));
                s += p * V;
        }
        o = vec4(exp(-2. * length(s - u)));
}





